vertexShader:
attribute float aPhase; attribute float aSize; uniform float uTime; varying float vA;
#include <fog_pars_vertex>
void main(){ float t = fract(uTime * 0.33 + aPhase); vA = 0.3 + 0.7 * (smoothstep(0.0, 0.06, t) * (1.0 - smoothstep(0.1, 0.34, t)));
  vec4 mvPosition = modelViewMatrix * vec4(position, 1.0); gl_Position = projectionMatrix * mvPosition;
  gl_PointSize = clamp(aSize * 260.0 / max(1.0, -mvPosition.z), 1.5, 22.0);
#include <fog_vertex>
}

fragmentShader:
uniform sampler2D uMap; uniform vec3 uCol; varying float vA;
#include <fog_pars_fragment>
void main(){ float a = texture2D(uMap, gl_PointCoord).r; if (a < 0.02) discard; gl_FragColor = vec4(uCol * (0.55 + 0.45 * vA), a * vA);
#include <fog_fragment>
}
